const urlBase64ToUint8Array = value => { const padding='='.repeat((4-value.length%4)%4); const base64=(value+padding).replace(/-/g,'+').replace(/_/g,'/'); const raw=window.atob(base64); return Uint8Array.from([...raw].map(c=>c.charCodeAt(0))); };


