  return <main className="app-shell"><header className="topbar"><button className="brand-button" onClick={onHome}>PICKLE BUSTER <span>V2</span></button><div className="topbar-note">LIVE DATABASE • PICKLE BUSTER SOCIAL PORTAL</div></header>{children}</main>
