  const createAjk=async e=>{e.preventDefault();setBusy(true);setMsg('');try{const username=String(ajkForm.username||'').trim().replace(/\s+/g,'-').toUpperCase();const displayName=String(ajkForm.display_name||'').trim();const password=String(ajkForm.password||'');if(!username)return setMsg('Username is required.');if(!/^[A-Z0-9._-]{3,40}$/.test(username))return setMsg('Username may contain only letters, numbers, dot, underscore or hyphen.');if(!displayName)return setMsg('Display name is required.');if(password.length<6)return setMsg('Temporary password must be at least 6 characters.');const {data,error}=await supabase.functions.invoke('admin-create-ajk',{body:{username,display_name:displayName,password}});if(error)throw new Error(error.message||'Create AJK request failed');if(data?.error)throw new Error(data.error);setMsg(`AJK created: ${data.username} · login username ${data.username}`);setAjkForm({username:'',display_name:'',password:''});await loadAjks()}catch(e){setMsg(e.message||'Unable to create AJK account.')}finally{setBusy(false)}};
  const updateAjkName=async(a,name)=>{const clean=String(name||'').trim();if(!clean||clean===String(a.display_name||'')){setAjkNameDrafts(x=>({...x,[a.id]:a.display_name||''}));return;}setBusy(true);setMsg('');try{const {error}=await supabase.from('app_users').update({display_name:clean}).eq('id',a.id);if(error)throw error;setMsg(`AJK name updated: ${clean}`);setAjkNameDrafts(x=>{const n={...x};delete n[a.id];return n});await loadAjks()}catch(e){setMsg(e.message||'Unable to update AJK name')}finally{setBusy(false)}};
