  const loadVenueCourts=async()=>{const [{data:v,error:ve},{data:c,error:ce}]=await Promise.all([supabase.from('venues').select('id,name,address,is_active').order('name'),supabase.from('courts').select('id,venue_id,court_name,court_number,is_active').order('court_number').order('court_name')]);if(ve)throw ve;if(ce)throw ce;setVenueCourts(c||[]);if(!selectedVenueId&&v?.length)setSelectedVenueId(v[0].id);};
  const saveVenue=async e=>{e.preventDefault();if(!venueForm.name.trim())return;setBusy(true);try{const {error}=await supabase.from('venues').insert({name:venueForm.name.trim(),address:venueForm.address.trim()||null,is_active:true});if(error)throw error;setVenueForm({name:'',address:''});await load();await loadVenueCourts();setMsg('Venue created')}catch(e){setMsg(e.message)}finally{setBusy(false)}};
