const saveEditedCourt=async e=>{e.preventDefault();if(!editingCourt?.court_name?.trim())return setMsg('Enter a court name.');setBusy(true);try{const {error}=await supabase.from('courts').update({court_name:editingCourt.court_name.trim(),court_number:editingCourt.court_number===''?null:Number(editingCourt.court_number)}).eq('id',editingCourt.id);if(error)throw error;setEditingCourt(null);await loadVenueCourts();setMsg('Court updated')}catch(e){setMsg(e.message)}finally{setBusy(false)}};
